                ["data"] = new JsonArray
                {
                    new JsonObject
                    {
                        ["id"] = 1,                                    // illustrative — do not hardcode
                        ["studentName"] = "Youssef Tarek",
                        ["studentCode"] = "STU000001",
                        ["studentPhoneNumber"] = "01000000030",
                        ["parentPhoneNumber"] = "01000000040",
