    private EndpointExampleSet RestoreStudent() => new()
    {
        Responses = new Dictionary<string, JsonNode>
        {
            ["200"] = SuccessEnvelope("Student restored to active list.", null),
            ["400"] = FailureEnvelope("Student is not in the recycle bin."),
            ["404"] = FailureEnvelope("Student not found.")
        }
    };

    private EndpointExampleSet BulkRestoreStudents() => new()
    {
        RequestBody = new JsonObject
        {
            ["studentIds"] = new JsonArray(1, 2)                       // illustrative ids
        },
        Responses = new Dictionary<string, JsonNode>
        {
            ["200"] = SuccessEnvelope("Students restored to active list.", null),
