    {
        Responses = new Dictionary<string, JsonNode>
        {
            ["200"] = SuccessEnvelope("Student permanently deleted.", null),
            ["404"] = FailureEnvelope("Student not found in recycle bin.")
        }
    };

    private EndpointExampleSet BulkImportStudents() => new()
    {
        RequestBody = new JsonObject
        {
            ["students"] = new JsonArray
            {
                new JsonObject
                {
                    ["studentName"] = "Youssef Tarek",
                    ["studentPhoneNumber"] = "01000000030",
                    ["parentPhoneNumber"] = "01000000040",
                    ["studentCode"] = "STU000001"
                },
                new JsonObject
                {
                    ["studentName"] = "Ahmed Khaled",
                    ["studentPhoneNumber"] = null,
                    ["parentPhoneNumber"] = null,
                    ["studentCode"] = null                             // auto-generated (REQ-STU-018)
                },
                new JsonObject
                {
                    ["studentName"] = "",                              // skipped — empty name (REQ-STU-018)
                    ["studentPhoneNumber"] = null,
                    ["parentPhoneNumber"] = null,
                    ["studentCode"] = null
                }
            }
        },
        Responses = new Dictionary<string, JsonNode>
        {
            ["200"] = SuccessEnvelope("Import completed.", new JsonObject
            {
                ["totalProcessed"] = 3,
                ["successCount"] = 2,
                ["failedCount"] = 1,
                ["failures"] = new JsonArray
                {
                    new JsonObject
                    {
                        ["rowNumber"] = 3,
                        ["studentName"] = "",
                        ["studentCode"] = null,
                        ["reason"] = "Student name is required."
                    }
                }
            }),
